<?php
namespace Opencart\Catalog\Model\Account;

class Trade extends \Opencart\System\Engine\Model {
	public function addProfile(int $customer_id, array $data): void {
		$this->db->query("REPLACE INTO `" . DB_PREFIX . "customer_trade` SET `customer_id` = '" . (int)$customer_id . "', `company` = '" . $this->db->escape((string)$data['company']) . "', `contact` = '" . $this->db->escape((string)$data['contact']) . "', `gstin` = '" . $this->db->escape((string)$data['gstin']) . "', `pan` = '" . $this->db->escape((string)$data['pan']) . "', `business_type` = '" . $this->db->escape((string)$data['business_type']) . "', `monthly_purchase` = '" . $this->db->escape((string)$data['monthly_purchase']) . "', `stores` = '" . $this->db->escape((string)$data['stores']) . "', `website` = '" . $this->db->escape((string)$data['website']) . "', `billing_address` = '" . $this->db->escape((string)$data['billing_address']) . "', `billing_city` = '" . $this->db->escape((string)$data['billing_city']) . "', `billing_postcode` = '" . $this->db->escape((string)$data['billing_postcode']) . "', `billing_country` = '" . $this->db->escape((string)$data['billing_country']) . "', `billing_zone` = '" . $this->db->escape((string)$data['billing_zone']) . "', `shipping_same` = '" . (int)$data['shipping_same'] . "', `shipping_address` = '" . $this->db->escape((string)$data['shipping_address']) . "', `shipping_city` = '" . $this->db->escape((string)$data['shipping_city']) . "', `shipping_postcode` = '" . $this->db->escape((string)$data['shipping_postcode']) . "', `shipping_country` = '" . $this->db->escape((string)$data['shipping_country']) . "', `shipping_zone` = '" . $this->db->escape((string)$data['shipping_zone']) . "', `trade_license` = '" . $this->db->escape((string)$data['trade_license']) . "', `pan_document` = '" . $this->db->escape((string)$data['pan_document']) . "', `cheque` = '" . $this->db->escape((string)$data['cheque']) . "', `reference` = '" . $this->db->escape((string)$data['reference']) . "'");
	}
}
